"""Reproduce the final all-training-data fits and write the submission JSON files.
Run identify.py, investigate.py and residual_analysis.py separately for exploration/CV.
"""
import json,numpy as np
from pathlib import Path
import wheel_model # installs the wheel response in identify.step
import identify as I
P=Path('models');P.mkdir(exist_ok=True)
COMMON_DATA='`data/train.csv`, all three trajectories and all 450 logged samples. Each trajectory is separate. Construct every complete overlapping window of 25 transitions (5 s), starting at sample indices 0 through 124: 125 windows per trajectory, 375 windows total. No window crosses a trajectory boundary. Each window starts from its logged pose; subsequent predictions use only simulated states. Unwrap `phi` within each trajectory before fitting; trigonometric position predictions are invariant to full turns. No rows are excluded. These windows target the intended simulation duration without treating noisy measured differences as exact velocities.'
COMMON_LIMIT='Training commands satisfy approximately `0.000034312 <= v_f <= 0.298155603` m/s and `-0.948147536 <= v_a <= 0.941160627` rad/s, computed on all training rows. Reverse motion and larger commands are not validated. Pose noise, actuator calibration drift and slip cannot be separated with these data. The expressions contain no previous command or actuator state: they cannot reproduce observed command carryover. Calibration coefficients are effective open-loop predictors, not uniquely identified mechanical parameters. Long-duration accuracy is not established by the 5 s fitting criterion. `phi_next` is deliberately unwrapped; periodic sine and cosine make position updates valid across heading wraps.'
BASE_ORIGIN='The translation-invariant terms `x` and `y`, the projection operators `cos` and `sin`, and heading accumulation came from planar differential-drive kinematics, not symbolic search. Initial diagnostics used within-trajectory pose differences and command-block phase. I compared Euler, constant-twist arc, affine bias, free phase, odd cubic, smooth dead-zone, angular/forward coupling, heading harmonics and lateral-slip structures. Sparse angular regression was diagnostic only; no genetic symbolic-regression search was used. Residuals were much larger at command changes and correlated within blocks, so final parameters were fitted to multi-step trajectories rather than one-step derivatives.'
REF='Unicycle/differential-drive kinematic model; see Steven M. LaValle, Planning Algorithms (2006), cited from memory without checking the book.'
def row(n,v,unit,description,fixed=False):return dict(name=n,value=float(v),unit=unit,type='fixed' if fixed else 'fitted',description=description)
def make(label,key,weights,family,origin,interpretation):
 fit=I.fit(key,[0,1,2],weights=weights);spec=I.SPECS[key];p=dict(zip(spec['names'],fit.x))
 params=[row('Ts',.2,'s','Sampling period supplied in TASK.md; fixed because the timestamps are equally spaced.',fixed=True)]
 desc={'gv':('-','Forward-command scale, estimated jointly in this candidate; not imported from another fit.'),'gw':('-','Angular-command scale, estimated jointly in this candidate; not imported from another fit.'),'bw':('rad/s','Constant angular-response offset, estimated jointly with all other fitted coefficients.'),'dz':('m/s' if key=='wheels' else 'rad/s','Symmetric static dead-zone threshold, estimated jointly with the other fitted parameters.'),'q':('-','Effective within-step angular phase fraction, estimated jointly; accounts mathematically for position/heading timing mismatch without adding command memory.'),'ell':('m','Effective half wheel separation in command-to-wheel-speed conversion, jointly estimated; not claimed to be the measured chassis geometry.')}
 for n in spec['names']:params.append(row(n,p[n],*desc[n]))
 if key=='euler':
  ex={'x_next':'x + Ts*gv*v_f*cos(phi)','y_next':'y + Ts*gv*v_f*sin(phi)','phi_next':'phi + Ts*gw*v_a'}
 elif key=='deadphase':
  w='(gw*sign(v_a)*Max(Abs(v_a)-dz,0)+bw)'
  ex={'x_next':f'x + Ts*gv*v_f*cos(phi + q*Ts*{w})','y_next':f'y + Ts*gv*v_f*sin(phi + q*Ts*{w})','phi_next':f'phi + Ts*{w}'}
 else:
  if key=='wheels':
   r='sign(v_f+ell*v_a)*Max(Abs(v_f+ell*v_a)-dz,0)';l='sign(v_f-ell*v_a)*Max(Abs(v_f-ell*v_a)-dz,0)'
   v=f'(gv*({r}+{l})/2)';w=f'(gw*({r}-{l})/(2*ell)+bw)'
  else:v='(gv*v_f)';w='(gw*v_a+bw)'
  z=f'(Ts*{w})'
  factor=f'Piecewise((1, Abs({z}) < eps), (sin({z}/2)/({z}/2), True))'
  params.append(row('eps',1e-7,'rad','Fixed numerical small-turn cutoff for the continuous zero-rate limit, chosen to avoid zero division; below this cutoff the sinc-factor error is less than 5e-16, dimensionless, by its Taylor expansion. This is not fitted.',fixed=True))
  ex={'x_next':f'x + Ts*{v}*{factor}*cos(phi + {z}/2)','y_next':f'y + Ts*{v}*{factor}*sin(phi + {z}/2)','phi_next':f'phi + {z}'}
 unit_note='`gv` and `gw` are dimensionless; `bw` is in rad/s; angular `dz` is in rad/s; wheel-model `dz` is in m/s; `ell` is in m; `q` is dimensionless, when present.'
 starts=', '.join(f'`{n} = {v}`'+(' '+desc[n][0] if desc[n][0]!='-' else '') for n,v in zip(spec['names'],spec['start']))
 bounds=', '.join(f'`{lo} <= {n} <= {hi}`'+(' '+desc[n][0] if desc[n][0]!='-' else '') for n,lo,hi in zip(spec['names'],spec['lo'],spec['hi']))
 if weights[1]==0 and weights[2]==0:
  criterion='Minimize the sum of squared `x` prediction errors at every step of every complete 25-transition open-loop window; no heading or `y` penalty. This directly matches the scored output and intended 5 s horizon. The two coefficients are sufficiently excited by the varied commands and headings; this estimator had the lowest pooled leave-one-trajectory-out `x` RMSE of the tested settings.'
 else:
  criterion='Minimize the sum, over every step of every complete 25-transition window, of squared `x` error plus squared heading error multiplied by `(0.15)**2`. Here the fixed heading weight is 0.15 m/rad; `y` has zero weight. This emphasizes the scored `x` output but regularizes angular calibration using measured heading. The weight was selected from the three explicitly tested choices (equal `x`/`y` weights with 0.3 m/rad heading weight, `x` only, and `x` with 0.15 m/rad heading weight), judged using held-out whole trajectories and parsimony.'
 method='Bound-constrained nonlinear least squares with `scipy.optimize.least_squares`, trust-region reflective algorithm (`method = trf`), finite-difference Jacobian, linear squared-error loss, `max_nfev = 400`, and `ftol = xtol = gtol = 1e-10` (dimensionless stopping tolerances). All fitted parameters were estimated together in one step in this final candidate; there is no parameter transfer. Starting values: '+starts+'. They come from diagnostic settled-command gains and small plausible offsets/thresholds, not held-out data. Bounds: '+bounds+'. Bounds enforce positive gains, moderate offsets and nondegenerate geometry while allowing timing adjustment; they are chosen constraints, not inferred confidence intervals. Nonlinear least squares is used because repeated state simulation and dead-zone/trigonometric terms depend nonlinearly on the coefficients; ordinary linear regression cannot optimize this rollout criterion. The procedure is deterministic and uses no random seed. '+unit_note+' For estimator comparison, refit from the same numerical starting values on each pair of trajectories and predict the third; the final reported coefficients use all three trajectories.'
 model={'expressions':ex,'parameters':params,'estimation':{'criterion':criterion,'data':COMMON_DATA,'method':method,'script':'deliver.py'},'discussion':{'family':family,'interpretation':interpretation,'origin':BASE_ORIGIN+' '+origin,'limitations':COMMON_LIMIT}}
 (P/(label+'.json')).write_text(json.dumps(model,indent=2))
 print(label,p,flush=True)
 return p

def run():
 make('Euler','euler',(1,0,0),REF+' Forward-Euler discretization.','This is the minimal baseline; projection uses the current heading rather than an assumed exact command response within the sample. Its small parameter count and held-out `x` error favor it despite inferior one-step heading residuals.','`x + Ts*gv*v_f*cos(phi)` and `y + Ts*gv*v_f*sin(phi)` add scaled commanded travel along the current heading; `phi + Ts*gw*v_a` accumulates scaled angular command. `Ts` is the sampling period, `gv` the forward gain and `gw` the angular gain. Both gains absorb unresolved calibration and timing effects; they are not ideal chassis constants.')
 make('ExactArc','bias',(1,0,.15),REF+' Zero-order-hold exact constant-twist integration with affine angular calibration.','The within-step arc and an additive angular offset were physically motivated alternatives to Euler. The offset was retained because it reduced full-trajectory heading drift in training, although its held-out 5 s benefit is not decisive.','`gv*v_f` is forward speed and `gw*v_a+bw` is angular speed; `bw` shifts angular response uniformly. Translation uses the midpoint angle `phi + Ts*(gw*v_a+bw)/2` and the chord-length factor `sin(Ts*(gw*v_a+bw)/2)/(Ts*(gw*v_a+bw)/2)`. The `Piecewise` branch substitutes the continuous zero-turn limit 1 below the numerical threshold `eps`. This integration is exact for an ideal constant body twist over `Ts`, not for the observed delayed actuator response.')
 make('AngularDeadZone','deadphase',(1,0,.15),'Static symmetric dead-zone command nonlinearity followed by a generalized midpoint unicycle update. '+REF,'Settled angular increments were suppressed near small `Abs(v_a)`; this motivated `sign(v_a)*Max(Abs(v_a)-dz,0)`, not a blind symbolic search. A fitted phase `q` was added after command-change residuals and the chord-angle diagnostic showed timing mismatch. Its fitted near-zero, slightly negative value is an empirical correction, not literal reverse time. This model is retained as a physically motivated nonlinear alternative despite somewhat worse held-out `x` performance than the simpler baseline.','`gw*sign(v_a)*Max(Abs(v_a)-dz,0)+bw` is angular response: commands inside threshold `dz` contribute no command-driven rotation, while excess magnitude is scaled by `gw`; `bw` supplies a constant offset. `gv*v_f` is forward response. Position projection uses `phi + q*Ts*(gw*sign(v_a)*Max(Abs(v_a)-dz,0)+bw)`; `q` shifts the effective direction within the discrete update. Heading accumulates the full angular increment. This model uses midpoint-type quadrature, without exact arc chord correction.')
 make('WheelDeadZone','wheels',(1,0,.15),'Differential-drive inverse kinematics, symmetric wheel-speed dead zones, and constant-twist arc integration. '+REF,'A forward/angular coupling diagnostic suggested that independent angular dead zones might miss wheel-level interactions. The derived virtual wheel commands `v_f+ell*v_a` and `v_f-ell*v_a` motivated applying the same threshold to each wheel. This is a physical-structure hypothesis, not a direct measurement of either wheel or a searched algebraic expression. All three trajectories excite these virtual commands; retain the model as a modest nonlinear alternative, not as a proven motor friction law.','The virtual right and left wheel speeds are `v_f+ell*v_a` and `v_f-ell*v_a`, where `ell` is effective half wheel separation. Each uses `sign(v_f+ell*v_a)*Max(Abs(v_f+ell*v_a)-dz,0)` or `sign(v_f-ell*v_a)*Max(Abs(v_f-ell*v_a)-dz,0)`. Their average times `gv` drives translation; their difference times `gw/(2*ell)` plus `bw` drives rotation. Constant-twist midpoint direction and sinc chord scaling then integrate the resulting twist. `dz` is an effective virtual-wheel speed threshold, not the angular threshold of the other nonlinear candidate. `ell`, `dz` and gains may trade off, since actual wheel-speed observations are absent.')
 pool={'order':['Euler','WheelDeadZone','ExactArc','AngularDeadZone'],'recommended':'Euler','reason':'The two-parameter Euler model had the lowest pooled leave-one-trajectory-out 5 s `x` RMSE among the tested family/criterion combinations (approximately 0.0291 m across all held-out windows in data/train.csv). It is translation invariant, compact and finite. The nonlinear alternatives explain settled-command residuals but do not consistently improve held-out `x` simulation. These validation windows overlap and involve only three trajectories, so the small differences are uncertain; this is not a claim about hidden test performance.'}
 (P/'pool.json').write_text(json.dumps(pool,indent=2))
if __name__=='__main__':run()
